// swift-tools-version: 6.2
import PackageDescription

/// BiathlonKit built for Android, with Java bindings generated by swift-java's jextract.
///
/// jextract's Swift thunks belong to the module they extract, so this package compiles
/// BiathlonKit's own sources (Sources/BiathlonKit links to them) as a module of the same
/// name, rather than depending on the iOS package.
let swiftSettings: [SwiftSetting] = [
    .enableUpcomingFeature("NonisolatedNonsendingByDefault"),
    .enableUpcomingFeature("InferIsolatedConformances"),
    .enableUpcomingFeature("ExistentialAny"),
]

let package = Package(
    name: "BiathlonKitAndroid",
    platforms: [.macOS(.v26)],
    products: [
        .library(name: "BiathlonKit", type: .dynamic, targets: ["BiathlonKit"])
    ],
    dependencies: [
        .package(url: "https://github.com/swiftlang/swift-java", .upToNextMinor(from: "0.7.0"))
    ],
    targets: [
        .target(
            name: "BiathlonKit",
            dependencies: [.product(name: "SwiftJava", package: "swift-java")],
            swiftSettings: swiftSettings,
            plugins: [.plugin(name: "JExtractSwiftPlugin", package: "swift-java")]
        )
    ]
)
